		"%s\n\t"
		"[--version] [-h|--help [-c|-C|--columns]]\n\t"
		"[-v|--verbose [-v|--verbose ...]] [-f|--force]\n\t"
		"[--checks] [--manglename {none|hex|auto}]\n\t"
